    private void initializeOccupancy() {
        shapeOccupancy.clear();
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                int id = SHAPE_ID_MAP[r][c];
                if (id != -1) {
                    shapeOccupancy.computeIfAbsent(id, k -> new ArrayList<>())
                            .add(new int[]{r, c});
                }
            }
        }
    }

    public void removeObstacle(int shapeId) {
        // Remove from the collision list so balls stop hitting it
        worldShapes.removeIf(s -> s.id == shapeId);

        // Wipe from the grid so the terrain returns to grass
        List<int[]> cells = shapeOccupancy.get(shapeId);
        if (cells != null) {
            for (int[] coord : cells) {
                SHAPE_ID_MAP[coord[0]][coord[1]] = -1;
                SERVER_MAP[coord[0]][coord[1]] = 0;
            }
            shapeOccupancy.remove(shapeId);
        }
    }

    // --- Inner Class for Data Structure ---
    public static class ServerShape {
        public static final int RECT = 0;
        public static final int ELLIPSE = 1;
        public static final int POLYGON = 2;

        public int id, terrainType, partnerId, formType;
        public double x, y, w, h;
        public double[] points;

        public ServerShape(int id, int terrain, int partnerId, int form, double x, double y, double w, double h) {
            this.id = id; this.terrainType = terrain; this.partnerId = partnerId;
            this.formType = form; this.x = x; this.y = y; this.w = w; this.h = h;
        }

        public ServerShape(int id, int terrain, int partnerId, int form, double[] points) {
            this.id = id; this.terrainType = terrain; this.partnerId = partnerId;
            this.formType = form; this.points = points;
        }
    }
